x(0, this.opacity); // Ensure opacity doesn\'t go below 0\n\n        // Bubble background\n        ctx.beginPath();\n        ctx.arc(this.x, this.y, this.radius, 0, Math.PI * 2);\n        ctx.fillStyle = \'rgba(0, 255, 0, 0.1)\'; // Semi-transparent green\n        ctx.fill();\n        ctx.strokeStyle = \'rgba(255, 255, 0, 0.5)\'; // Yellow\n        ctx.lineWidth = 1;\n        ctx.stroke();\n\n        // Text\n        ctx.fillStyle = \'#0000FF\'; // Blue\n        ctx.font = `bold ${Math.max(10, this.radius * 0.6)}px Comic Sans MS`;\n        ctx.textAlign = \'center\';\n        ctx.textBaseline = \'middle\';\n        ctx.fillText(this.text, this.x, this.y);\n\n        ctx.restore();\n    }\n}\n\nfunction getRandomInt(min, max) {\n    return Math.floor(Math.random() * (max - min + 1)) + min;\n}\n\nfunction updateIntensityMeter() {\n    storyIntensity = Math.max(0, storyIntensity - INTENSITY_DECAY); // Decay over time\n    intensityFill.style.height = `${storyIntensity}%`;\n}\n\nlet lastTime = 0;\nfunction animate(currentTime) {\n    const deltaTime = currentTime - lastTime;\n    lastTime = currentTime;\n\n    ctx.clearRect(0, 0, canvas.width, canvas.height);\n\n    drawMicrophone();\n\n    if (isPlaying) {\n        // Generate new waves\n        if (currentTime - lastWaveTime \u003e waveInterval \u0026\u0026 waves.length \u003c MAX_WAVES) {\n            waves.push(new Wave(mic.x, mic.y));\n            lastWaveTime = currentTime;\n        }\n\n        // Generate new story bubbles\n        if (currentTime - lastBubbleTime \u003e currentBubbleInterval \u0026\u0026 storyBubbles.length \u003c MAX_BUBBLES) {\n            const randomStory = stories[getRandomInt(0, stories.length - 1)];\n            storyBubbles.push(new StoryBubble(mic.x, mic.y, randomStory));\n            storyIntensity = Math.min(100, storyIntensity + INTENSITY_INCREASE); // Increase intensity\n            currentBubbleInterval = getRandomInt(bubbleIntervalMin, bubbleIntervalMax); // New random interval\n