                  '\u003c!DOCTYPE html\u003e\n\u003chtml lang="en"\u003e\n\u003chead\u003e\n    \u003cmeta charset="UTF-8"\u003e\n    \u003cmeta name="viewport" content="width=device-width, initial-scale=1.0"\u003e\n    \u003ctitle\u003eSnake Game\u003c/title\u003e\n    \u003clink rel="stylesheet" href="styles.css"\u003e\n\u003c/head\u003e\n\u003cbody\u003e\n    \u003cdiv id="game-container"\u003e\n        \u003ccanvas id="game-board"\u003e\u003c/canvas\u003e\n        \u003cdiv id="game-info"\u003e\n            \u003cdiv id="score"\u003eScore: 0\u003c/div\u003e\n            \u003cdiv id="high-score"\u003eHigh Score: 0\u003c/div\u003e\n            \u003cselect id="difficulty"\u003e\n                \u003coption value="easy"\u003eEasy\u003c/option\u003e\n                \u003coption value="medium"\u003eMedium\u003c/option\u003e\n                \u003coption value="hard"\u003eHard\u003c/option\u003e\n            \u003c/select\u003e\n            \u003cbutton id="start-button"\u003eStart Game\u003c/button\u003e\n            \u003cbutton id="music-toggle"\u003eToggle Music\u003c/button\u003e\n        \u003c/div\u003e\n        \u003cdiv id="customization"\u003e\n            \u003clabel for="snake-color"\u003eSnake Color:\u003c/label\u003e\n            \u003cinput type="color" id="snake-color" value="#00ff00"\u003e\n            \u003clabel for="food-color"\u003eFood Color:\u003c/label\u003e\n            \u003cinput type="color" id="food-color" value="#ff0000"\u003e\n        \u003c/div\u003e\n    \u003c/div\u003e\n    \u003cdiv id="leaderboard"\u003e\n        \u003ch2\u003eLeaderboard\u003c/h2\u003e\n        \u003col id="high-scores"\u003e\u003c/ol\u003e\n    \u003c/div\u003e\n    \u003caudio id="background-music" loop\u003e\n        \u003csource src="data:audio/mpeg;base64," type="audio/mpeg"\u003e\n    \u003c/audio\u003e\n    \u003cscript src="index.js"\u003e\u003c/script\u003e\n\u003c/body\u003e\n\u003c/html\u003e',
